tagsDecl.rendition:
display: grid;
grid-template-columns: max-content 1fr;
column-gap: 0.6em;
row-gap: 0.35em;
margin: 0.5em 0 0.5em 1.5em;

& dd & :first-child {
margin-top: 0;
}

& dt {
font-weight: normal;
float: none !important;
clear: none !important;
margin: 0 !important;
padding: 0 !important;
}

& dd {
margin: 0 !important;
padding: 0 !important;
}
